"""RT-20261002-df803b, J4 item (i): extract every sentence of the three bound files
(and the text of the two code blocks) that mentions a keyword of the plan's attack
item (i). Text processing only."""
import json, re, sys, yaml
KEY = re.compile(r"frontier|S\s?T\^2|S\*T\^2|\bfirst\b|below T_gen|under T_gen|\bbeats?\b|validated|m >= 4|m>=4|m ≥ 4", re.I)
SPLIT = re.compile(r"(?<=[a-z0-9\)\]'\"%])\.\s+(?=[A-Z(\"'])|;\s+|\n\s*\n")
def leaves(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from leaves(v, f"{path}.{k}" if path else str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from leaves(v, f"{path}[{i}]")
    elif isinstance(o, str):
        yield path, o
rows = []
for fn in sys.argv[1:]:
    raw = open(fn).read()
    rawlines = raw.split("\n")
    # comment lines (YAML # comments are not in the parsed tree)
    for i, ln in enumerate(rawlines, 1):
        st = ln.strip()
        if st.startswith("#") and KEY.search(st):
            rows.append({"file": fn, "path": "#comment", "line": i, "text": st})
    d = yaml.safe_load(raw)
    for path, text in leaves(d):
        code = path.endswith("fixture_code") or path.endswith("stage0_code")
        if code:
            for j, ln in enumerate(text.split("\n")):
                if KEY.search(ln):
                    rows.append({"file": fn, "path": path, "line": f"code+{j+1}", "text": ln.strip()})
            continue
        flat = re.sub(r"\s+", " ", text)
        for sent in SPLIT.split(flat):
            if KEY.search(sent):
                frag = sent[:60]
                ln = next((i for i, l in enumerate(rawlines, 1) if frag[:30] in re.sub(r"\s+", " ", l)), None)
                rows.append({"file": fn, "path": path, "line": ln, "text": sent.strip()})
json.dump(rows, open("sentences.json", "w"), indent=1)
from collections import Counter
print(len(rows), Counter(r["file"] for r in rows))
print(Counter((r["file"], "code" if str(r["line"]).startswith("code") else ("comment" if r["path"] == "#comment" else "text")) for r in rows))

