import re, yaml, json
SEC = re.compile(r"TW-01|containment|matched advice|below rho|below any|meets? any budget|speedup|breakthrough|\bbreak\b|exponent", re.I)
PRI = re.compile(r"frontier|S\s?T\^2|S\*T\^2|\bfirst\b|below T_gen|under T_gen|\bbeats?\b|validated|m >= 4", re.I)
SPLIT = re.compile(r"(?<=[a-z0-9\)\]'\"%])\.\s+(?=[A-Z(\"'])|;\s+")
def leaves(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items(): yield from leaves(v, f"{path}.{k}" if path else str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o): yield from leaves(v, f"{path}[{i}]")
    elif isinstance(o, str): yield path, o
extra = []
for fn in ("H.yaml", "E.yaml", "A.yaml"):
    d = yaml.safe_load(open(fn))
    for path, text in leaves(d):
        if path.endswith("_code"): continue
        for s in SPLIT.split(re.sub(r"\s+", " ", text)):
            if SEC.search(s) and not PRI.search(s):
                extra.append({"file": fn, "path": path, "text": s.strip()})
json.dump(extra, open("sentences_secondary.json", "w"), indent=1)
print(len(extra))
